41:  it("a single sword (base 100 G) for a newcomer → premium 115 G (100 + 10 first insurance + 5 fee)", () => {
49:  it("a single amulet (base 60 G) for a newcomer → premium 71 G (60 + 6 + 5)", () => {
57:  it("a single staff (base 80 G) for a newcomer → premium 93 G (80 + 8 + 5)", () => {
65:  it("a single potion (base 40 G) for a newcomer → premium 49 G (40 + 4 + 5)", () => {
75:  it("2 runes → 50 G base premium (newcomer, first quote: 50 + 5 + 5 = 60 G premium)", () => {
83:  it("3 runes → 60 G base premium, block applies (newcomer, first quote: 60 + 6 + 5 = 71 G premium)", () => {
96:  it("4 runes → 100 G base premium, no block since a block requires exactly 3 (newcomer, first quote: 100 + 10 + 5 = 115 G premium)", () => {
114:  it("7 runes → 175 G base premium (newcomer, first quote: 175 + 17.5 + 5 = 197.5 → rounded up to 198 G premium)", () => {
